import{_ as t,o,c as s,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"OS Kernel Sandboxing & Network Isolation","description":"","frontmatter":{},"headers":[],"relativePath":"security/os-sandboxing.md","filePath":"security/os-sandboxing.md","lastUpdated":1795286990000}'),n={name:"security/os-sandboxing.md"};function a(i,e,l,c,r,p){return o(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="os-kernel-sandboxing-network-isolation" tabindex="-1">OS Kernel Sandboxing &amp; Network Isolation <a class="header-anchor" href="#os-kernel-sandboxing-network-isolation" aria-label="Permalink to &quot;OS Kernel Sandboxing &amp; Network Isolation&quot;">​</a></h1><p>JetPack runs native host processes without virtual machines by confining every primary worker (<code>[execution]</code>) and companion service (<code>[services.&lt;name&gt;]</code>) inside an operating-system kernel sandbox. If no sandbox implementation exists for the host OS, worker launch fails with <code>JetPackError::SandboxError</code> before any process is spawned.</p><h2 id="cross-platform-kernel-sandbox-matrix" tabindex="-1">Cross-Platform Kernel Sandbox Matrix <a class="header-anchor" href="#cross-platform-kernel-sandbox-matrix" aria-label="Permalink to &quot;Cross-Platform Kernel Sandbox Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Security Dimension</th><th style="text-align:left;">Windows (<code>windows/amd64</code>)</th><th style="text-align:left;">macOS (<code>darwin/arm64</code>)</th><th style="text-align:left;">Linux (<code>linux/amd64</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Kernel Mechanism</strong></td><td style="text-align:left;"><strong>AppContainer</strong> (<code>CreateAppContainerProfile</code>) + <strong>Low Integrity SID</strong></td><td style="text-align:left;"><strong>Apple Seatbelt</strong> (<code>sandbox_init</code> with inline SBPL <code>(deny default)</code>)</td><td style="text-align:left;">Unprivileged <strong>Bubblewrap (<code>bwrap</code>)</strong> namespaces + <strong>Landlock LSM</strong> (<code>SYS_LANDLOCK_RESTRICT_SELF</code> via <code>sandbox-landlock-exec</code>)</td></tr><tr><td style="text-align:left;"><strong>Process Tree Cleanup</strong></td><td style="text-align:left;">Win32 <strong>Job Object</strong> with <code>JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE</code></td><td style="text-align:left;">Process group <code>killpg</code> (<code>SIGKILL</code> after grace period)</td><td style="text-align:left;">Namespace / PID isolation + <code>killpg</code> cleanup</td></tr><tr><td style="text-align:left;"><strong>Job Workspace Access</strong></td><td style="text-align:left;">Explicit NTFS DACL (<code>SetNamedSecurityInfoW</code>) granting Read/Write on <code>&lt;root&gt;/workspaces/job_&lt;id&gt;</code></td><td style="text-align:left;">SBPL <code>file-read*</code> + <code>file-write*</code> limited to <code>&lt;root&gt;/workspaces/job_&lt;id&gt;</code></td><td style="text-align:left;"><code>--bind</code> + Landlock RW rule on <code>&lt;root&gt;/workspaces/job_&lt;id&gt;</code></td></tr><tr><td style="text-align:left;"><strong>Shared Runtimes Access</strong></td><td style="text-align:left;">Explicit NTFS DACL Read-Only on <code>&lt;root&gt;/runtimes/</code></td><td style="text-align:left;">SBPL <code>file-read*</code> on <code>&lt;root&gt;/runtimes/</code> + system libs (<code>/System</code>, <code>/usr/lib</code>, <code>dyld</code>)</td><td style="text-align:left;"><code>--ro-bind</code> + Landlock RO rule on <code>&lt;root&gt;/runtimes/</code></td></tr><tr><td style="text-align:left;"><strong>User Files (<code>~/Documents</code>, etc.)</strong></td><td style="text-align:left;"><strong>Denied by default</strong> (Low Integrity AppContainer lacks user profile ACLs)</td><td style="text-align:left;"><strong>Denied by default</strong> (<code>EPERM</code> / <code>Operation not permitted</code>)</td><td style="text-align:left;"><strong>Denied by default</strong> (<code>pivot_root</code> + Landlock LSM)</td></tr><tr><td style="text-align:left;"><strong>Direct Host Network</strong></td><td style="text-align:left;"><strong>Denied by default</strong> (no internetClient capability granted to AppContainer)</td><td style="text-align:left;"><strong>Denied by default</strong> (<code>(deny default)</code> blocks outbound sockets &amp; Mach services)</td><td style="text-align:left;"><strong>Denied by default</strong> (<code>CLONE_NEWNET</code> creates isolated loopback-only netns)</td></tr><tr><td style="text-align:left;"><strong>GPU Acceleration Gate</strong> (<code>permissions.gpu_access = true</code>)</td><td style="text-align:left;">DirectML / CUDA device access permitted inside sandbox</td><td style="text-align:left;">Conditional <code>(allow iokit-open (iokit-user-client-class &quot;AGXDeviceUserClient&quot;))</code></td><td style="text-align:left;">Conditional <code>--dev-bind</code> for <code>/dev/dri</code> and <code>/dev/nvidia*</code></td></tr><tr><td style="text-align:left;"><strong>Cleanup on Exit</strong></td><td style="text-align:left;">Deletes per-job <code>AppContainer</code> profile + closes Job Object handle</td><td style="text-align:left;">Releases sandboxed child process &amp; job workspace</td><td style="text-align:left;">Tears down <code>bwrap</code> mounts &amp; kills process tree</td></tr></tbody></table><h2 id="default-deny-policy-app-toml-permissions" tabindex="-1">Default-Deny Policy &amp; <code>app.toml</code> Permissions <a class="header-anchor" href="#default-deny-policy-app-toml-permissions" aria-label="Permalink to &quot;Default-Deny Policy &amp; `app.toml` Permissions&quot;">​</a></h2><p>When <code>[permissions]</code> is omitted from <code>app.toml</code>, JetPack applies strict defaults:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permissions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filesystem_scopes = []</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">network_allowlist = []</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gpu_access = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><ul><li><strong>No absolute host paths</strong>: Manifest validation rejects any path containing <code>..</code>, leading <code>/</code>, Windows drive prefixes, or <code>~</code> in <code>filesystem_scopes</code>.</li><li><strong>No dynamic linker hijacking</strong>: <code>[execution].env</code> and <code>[services.&lt;name&gt;].env</code> reject <code>LD_PRELOAD</code>, <code>LD_LIBRARY_PATH</code>, <code>LD_AUDIT</code>, <code>DYLD_INSERT_LIBRARIES</code>, <code>DYLD_LIBRARY_PATH</code>, <code>DYLD_FRAMEWORK_PATH</code>, <code>PYTHONINSPECT</code>, and <code>PYTHONPATH</code>.</li><li><strong>Guaranteed VRAM/RAM reclamation</strong>: When a WebSocket session disconnects, <code>jetpack-daemon</code> shuts down, or a worker exceeds <code>execution.timeout_secs</code>, <code>WorkerLifecycleManager</code> sends a termination signal and forcefully reaps the entire process tree after <code>graceful_shutdown_secs</code> (<code>10s</code> default), releasing GPU VRAM immediately.</li></ul><h2 id="local-ipc-userspace-network-proxy" tabindex="-1">Local IPC &amp; Userspace Network Proxy <a class="header-anchor" href="#local-ipc-userspace-network-proxy" aria-label="Permalink to &quot;Local IPC &amp; Userspace Network Proxy&quot;">​</a></h2><p>Because sandboxed workers have <strong>no direct access to host network interfaces</strong>, outbound traffic is brokered exclusively by <code>jetpack-daemon</code>:</p><h3 id="_1-kernel-authenticated-local-ipc" tabindex="-1">1. Kernel-Authenticated Local IPC <a class="header-anchor" href="#_1-kernel-authenticated-local-ipc" aria-label="Permalink to &quot;1. Kernel-Authenticated Local IPC&quot;">​</a></h3><ul><li><strong>macOS &amp; Linux</strong>: Unix Domain Socket at <code>&lt;root&gt;/workspaces/job_&lt;id&gt;/ipc.sock</code> with strict <code>0o600</code> file permissions.</li><li><strong>Windows</strong>: Named Pipe <code>\\\\.\\pipe\\jetpack-worker-&lt;job_id&gt;</code> configured with an explicit DACL allowing only the current user SID and the job&#39;s dedicated AppContainer SID (<code>S-1-15-2-...</code>).</li></ul><h3 id="_2-userspace-network-proxy-permissions-network-allowlist" tabindex="-1">2. Userspace Network Proxy (<code>permissions.network_allowlist</code>) <a class="header-anchor" href="#_2-userspace-network-proxy-permissions-network-allowlist" aria-label="Permalink to &quot;2. Userspace Network Proxy (`permissions.network_allowlist`)&quot;">​</a></h3><p><code>jetpack-daemon</code> runs an asynchronous userspace HTTP/CONNECT proxy exposed to the worker via <code>JETPACK_PROXY_ENDPOINT</code> (plus <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>ALL_PROXY</code>):</p><ol><li><strong>Allowlist Matching</strong>: Every outbound <code>CONNECT</code> or HTTP request checks the destination <code>host:port</code> against <code>permissions.network_allowlist</code> in <code>app.toml</code> (supports exact matches like <code>api.openai.com:443</code>, wildcard subdomains like <code>*.huggingface.co:443</code>, and explicit non-loopback endpoints).</li><li><strong>Forbidden Rules</strong>: Global wildcards (<code>*</code>, <code>*:*</code>, <code>0.0.0.0:*</code>) are rejected at manifest validation time (<code>crates/jetpack-common/src/manifest.rs</code>), and workers cannot target <code>127.0.0.1:9470</code> or daemon internal ports through the proxy.</li><li><strong>Blocking &amp; Audit Logging</strong>: Requests to unlisted domains are rejected immediately with <code>403 Forbidden</code> before opening any upstream TCP socket, and a security audit event is logged by <code>jetpack-daemon</code>. Raw <code>connect()</code> syscalls bypassing the proxy fail at the kernel level (<code>ENETUNREACH</code>, <code>EPERM</code>, or <code>WSAEACCES</code>).</li></ol>',15)])])}const h=t(n,[["render",a]]);export{u as __pageData,h as default};
